INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Lohnsteuer nur für IT-Mitarbeiter gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Arbeitnehmer"}, {"text": "Ja", "correct": false, "because": "Nicht branchenspezifisch"}]'),
