('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Lohnsteuer für IT-Mitarbeiter berechne?', 3, '[{"text": "Einkommenshöhe", "correct": false, "because": "Bestimmt Steuer"}, {"text": "Steuerklasse", "correct": false, "because": "Beeinflusst Abzug"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Steuerfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Wird Lohnsteuer nur für Vollzeitkräfte erhoben?', 3, '[{"text": "Nein", "correct": true, "because": "Auch für Teilzeit"}, {"text": "Ja", "correct": false, "because": "Gilt für alle"}]'),
